REPORTS_SERVICE_TOKEN=s3cret node -e '
const { requireLogin } = require("./auth");
const call = (headers) => {
  let out = "next";
  const res = { status: (c) => ({ json: () => { out = c; } }) };
  requireLogin({ headers }, res, () => { out = "next"; });
  return out;
};
const cases = [
  ["no creds", {}, 401],
  ["session cookie", { cookie: "session=abc" }, "next"],
  ["good token", { authorization: "Bearer s3cret" }, "next"],
  ["wrong token", { authorization: "Bearer nope" }, 401],
  ["empty bearer", { authorization: "Bearer " }, 401],
  ["not bearer", { authorization: "s3cret" }, 401],
];
let fail = 0;
for (const [name, h, want] of cases) {
  const got = call(h);
  const ok = got === want;
  if (!ok) fail++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}: got ${got}, want ${want}`);
}
process.exit(fail);
'

